<?php /** Audited mutations are filtered by current device visibility and network permissions. */ ?>
<?php if($workspace_audit) { ?><section class="nms-panel"><h2>Change history</h2><div class="nms-table-wrap"><table class="nms-table" data-server-pagination="true"><thead><tr><th>When</th><th>Action / account</th><th>Device / network</th><th>Details</th></tr></thead><tbody>
<?php foreach($workspace_audit['rows'] as $event) { ?><tr><td><?php print nms_h($event['created_at']); ?></td><td><?php print nms_h(str_replace('_',' ',$event['action'])); ?> · #<?php print (int)$event['user_id']; ?></td><td><?php print nms_h($event['description'] ?: 'Network #'.$event['network_id']); ?></td><td><pre><?php print nms_h(json_encode(json_decode($event['detail_json'],true),JSON_PRETTY_PRINT|JSON_INVALID_UTF8_SUBSTITUTE)); ?></pre></td></tr><?php } if(!$workspace_audit['rows']) { ?><tr><td colspan="4">No recorded changes in this selection.</td></tr><?php } ?></tbody></table></div>
<p>Page <?php print (int)$workspace_audit['page']; ?> of <?php print (int)$workspace_audit['pages']; ?><?php foreach(['Previous'=>-1,'Next'=>1] as $label=>$delta) {$next=$workspace_audit['page']+$delta;if($next<1 || $next>$workspace_audit['pages'])continue; ?> · <a href="<?php print nms_h(nms_workspace_url('history',$workspace_id,['audit_page'=>$next])); ?>"><?php print $label; ?></a><?php } ?></p></section><?php } ?>
